static int hexColor(char c) {
    if (c >= '0' && c <= '9') return c - '0';
    if (c >= 'A' && c <= 'F') return c - 'A' + 10;
    if (c >= 'a' && c <= 'f') return c - 'a' + 10;
    return 7;
}

// Prints text using a same-shaped mask of hex color digits, switching color() only when it changes.
static void printMasked(const char* text, const char* mask, int baseColor) {
    if (!mask) { color(baseColor); std::cout << text << std::endl; return; }
    std::string t(text), m(mask), run;
    size_t ti = 0, mi = 0; int cur = -1;
    while (ti <= t.size()) {
        bool eol = ti == t.size() || t[ti] == '\n';
        if (eol) {
            if (!run.empty()) { std::cout << run; run.clear(); }
            std::cout << '\n';
            while (mi < m.size() && m[mi] != '\n') mi++;
            mi++; ti++;
            if (ti > t.size()) break;
            continue;
        }
        int c = (mi < m.size() && m[mi] != '\n') ? hexColor(m[mi]) : baseColor;
        if (c != cur) { if (!run.empty()) { std::cout << run; run.clear(); } color(c); cur = c; }
        run += t[ti]; ti++;
        if (mi < m.size() && m[mi] != '\n') mi++;
    }
    std::cout << std::flush;
}

void showArt(const char* art) { std::cout << art << std::endl; }

void playAnim(const ArtAnim& a) {
    for (int i = 0; i < a.count; i++) {
        clear();
        printMasked(a.frames[i].text, a.frames[i].mask, a.baseColor);
        frameSleep(a.frames[i].holdMs);  // Ultra Deluxe: not MSdelay, so web Text speed "Instant" doesn't skip it
    }
    color(7);
}

static int who(const std::string& n) {
    if (n == "Broomba") return 0;
    if (n == "JetWet" || n == "Swifter JetWet") return 1;
    return 2;   // BysonV8
}
void showSelectArt(const std::string& n) {
    const char* a[] = { Art::BROOMBA_LARGE_FRONT, Art::JETWET_LARGE_FRONT, Art::BYSON_LARGE_FRONT };
    showArt(a[who(n)]);
}
void showCombatArt(const std::string& n) {
    const char* a[] = { Art::BROOMBA_SMALL_FRONT, Art::JETWET_SMALL_FRONT, Art::BYSON_SMALL_FRONT };
    showArt(a[who(n)]);
}
void playAttackAnim(const std::string& n) {
    const ArtAnim* a[] = { &Art::ATTACK_BROOMBA_SMALL, &Art::ATTACK_JETWET_SMALL, &Art::ATTACK_BYSON_SMALL };
    playAnim(*a[who(n)]);
}
void playTitleIntro() {
    // Plays the intro, then holds on the title screen until the player presses Enter.
    // (The last frames of TITLE_INTRO are an idle loop; a still title is used here so it
    //  works the same in the terminal and web builds without non-blocking input.)
    ArtAnim intro = Art::TITLE_INTRO; intro.count -= 3;
    playAnim(intro);
    std::string line; std::getline(std::cin, line);
    color(7);
}
void playEndingCredits()      { playAnim(Art::ENDING_CREDITS); }
void playPutridFirstMeeting() { playAnim(Art::PUTRID_FIRST_MEETING); }
void playPutridReturnVisit()  { playAnim(Art::PUTRID_RETURN_VISIT); }

void printMaskedPublic(const char* text, const char* mask, int baseColor) { printMasked(text, mask, baseColor); }

void playMailbox(const std::string& c) {
    if (c == "letter") playAnim(Art::MAILBOX_LETTER);
    else if (c == "rat") playAnim(Art::MAILBOX_RAT);
    else if (c == "mirror") playAnim(Art::MAILBOX_MIRROR);
    else if (c == "box") playAnim(Art::MAILBOX_BOX);
    else if (c == "mucus") playAnim(Art::MAILBOX_MUCUS);
    else playAnim(Art::MAILBOX_EMPTY);
}
static void showPic(const ArtFrame& f) { clear(); printMasked(f.text, f.mask, 7); color(7); }
void showRatNote() { showPic(Art::PIC_RAT_NOTE); }
void showMirror(const std::string& n) {
    const ArtFrame* a[] = { &Art::PIC_MIRROR_BROOMBA, &Art::PIC_MIRROR_JETWET, &Art::PIC_MIRROR_BYSON };
    showPic(*a[who(n)]);
}
void showBox(bool mucus) { showPic(mucus ? Art::PIC_BOX_MUCUS : Art::PIC_BOX); }

// ---------------------------------------------------------------- letters
// A letter is drawn all at once inside a paper border. Text is word-wrapped to fit,
// so any letter (including new milestone letters) can use it.
namespace {
const int LW = 62;          // letter width (outer)
const int LX = 9;           // left margin so the letter sits centered in 80 columns
const int TEXT_W = 50;      // usable text width inside the paper

struct Sheet {
    std::vector<std::string> t, m;
    void add(const std::string& text, const std::string& mask) { t.push_back(text); m.push_back(mask); }
    void add(const std::string& text, char col) { add(text, std::string(text.size(), col)); }
};

std::vector<std::string> wrapText(const std::string& s, int width) {
    std::vector<std::string> out; std::string line, word;
    auto flush = [&]() { if (!word.empty()) {
        if (!line.empty() && (int)(line.size() + 1 + word.size()) > width) { out.push_back(line); line.clear(); }
        line += (line.empty() ? "" : " ") + word; word.clear(); } };
    for (char ch : s) { if (ch == ' ') flush(); else word += ch; }
    flush(); if (!line.empty()) out.push_back(line);
    if (out.empty()) out.push_back("");
    return out;
}

// One row of paper: left edge, text at an indent, right edge, all LW wide.
void row(Sheet& s, const std::string& L, const std::string& R, char edgeCol,
         const std::string& text = "", int indent = 0, char textCol = '7') {
    int inner = LW - (int)L.size() - (int)R.size();
    std::string mid(inner, ' ');
    std::string mmid(inner, '7');
    for (size_t i = 0; i < text.size() && indent + (int)i < inner; i++) mmid[indent + i] = textCol;
    for (size_t i = 0; i < text.size() && indent + (int)i < inner; i++) mid[indent + i] = text[i];
    s.add(L + mid + R, std::string(L.size(), edgeCol) + mmid + std::string(R.size(), edgeCol));
}
} // namespace

static std::string rep(char c, int n) { return std::string(n > 0 ? n : 0, c); }

void showLetter(LetterStyle style, const std::string& greeting, const std::vector<std::string>& body,
                const std::string& closing, const std::string& signer, int signerColor) {
    // Every page is LW (62) columns wide: left edge at column 0, right edge at column 61.
    Sheet s;
    char edge = '7', sig = "0123456789ABCDEF"[signerColor & 15];
    std::string L = "|", R = "|";
    switch (style) {
    case LETTER_SCROLL:      // rolled parchment, in Janitorius's gold
        edge = '6'; L = "   |";
        s.add("  " + rep('_', 59), '6');
        s.add(" / \\" + rep(' ', 57) + "\\", '6');
        s.add("|  |" + rep(' ', 57) + "|", '6');
        s.add(" \\_|" + rep(' ', 57) + "|", '6');
        break;
    case LETTER_NOTEPAD: {   // spiral notepad page
        std::string holes = rep(' ', 61), top = " " + rep('_', 60);
        for (int c = 3; c < 59; c += 5) { holes[c] = 'o'; top[c] = '|'; }
        s.add(holes, '8'); s.add(top, '7');
        break; }
    case LETTER_FORMAL: {    // heavy double border with a crest
        L = "||"; R = "||";
        s.add("+" + rep('=', 60) + "+", '7');
        row(s, L, R, edge);
        row(s, L, R, edge, ".----.", 26, '6');
        row(s, L, R, edge, "( SM )", 26, 'E');
        row(s, L, R, edge, "'----'", 26, '6');
        break; }
    default:                 // plain page with a folded corner
        s.add("." + rep('-', 57) + ".", '7');
        s.add("|" + rep(' ', 57) + "|\\", '7');
        s.add("|" + rep(' ', 57) + "'--\\", '7');
        break;
    }

    row(s, L, R, edge);
    row(s, L, R, edge, greeting, 3, '7');
    row(s, L, R, edge);
    for (const std::string& para : body)
        for (const std::string& ln : wrapText(para, TEXT_W - 4)) row(s, L, R, edge, ln, 7, '7');
    row(s, L, R, edge);
    row(s, L, R, edge, closing, 3, '7');
    row(s, L, R, edge, signer, 9, sig);
    row(s, L, R, edge);

    switch (style) {
    case LETTER_SCROLL:
        s.add("   |   " + rep('_', 54) + "|_", '6');
        s.add("   |  /" + rep(' ', 55) + "/", '6');
        s.add("   \\_/" + rep('_', 56) + "/", '6');
        break;
    case LETTER_NOTEPAD: {
        std::string torn = "|";
        for (int i = 0; i < 30; i++) torn += "/\\";
        s.add(torn + "|", '7');
        break; }
    case LETTER_FORMAL:
        s.add("+" + rep('=', 60) + "+", '7');
        break;
    default:
        s.add("'" + rep('-', 60) + "'", '7');
        break;
    }

    clear();
    std::cout << '\n';
    std::string text, mask;
    for (size_t i = 0; i < s.t.size(); i++) {
        text += std::string(LX, ' ') + s.t[i] + '\n';
        mask += std::string(LX, '7') + s.m[i] + '\n';
    }
    printMaskedPublic(text.c_str(), mask.c_str(), 7);
    color(7);
}
